const G_PER_LB = 454; // business rounding: 454g = 1lb
const APP_VERSION = "26.10.5"; // format: <year>.<minor>.<patch> — patch counts 1-9 each minor, then rolls the minor up and patch resets to 1 (e.g. 26.3.9 -> 26.4.1); bump minor first digit only each new year
