// Used to power "quick-fill from a recent batch" — sorts by whichever delivery/addition was most
// recently logged (not when the batch/lot was first created), so a batch that just got a new
// delivery this week bubbles back to the top even if it was originally created weeks ago.
function lastActivityTime(item, subListKey) {
  const subList = item[subListKey];
  if (subList && subList.length > 0) return Math.max(...subList.map((s) => s.createdAt || 0));
  return item.createdAt || 0;
}
function recentDistinct(list, keyFn, subListKey, limit = 8) {
  const seen = new Set();
  const result = [];
  [...(list || [])].sort((a, b) => lastActivityTime(b, subListKey) - lastActivityTime(a, subListKey)).forEach((item) => {
    const key = keyFn(item);
    if (seen.has(key)) return;
    seen.add(key);
    result.push(item);
  });
  return result.slice(0, limit);
}
// A Metrc package tag should never be logged twice — it identifies one physical package. Checks
// both what's already been submitted (existingList, e.g. batches or bucked lots) and whatever's
// currently staged in this manifest but not yet submitted (lineItems), so a double-tap on "Add
// Item" gets caught before it ever reaches the database.
function findPackageTagOwner(tag, existingList, subListKey, lineItems) {
  const tagLower = (tag || "").trim().toLowerCase();
  if (!tagLower) return null;
  for (const item of (existingList || [])) {
    const subList = item[subListKey];
    const entries = (subList && subList.length > 0) ? subList : [{ packageTag: item.packageTag }];
    for (const entry of entries) {
      if (entry.packageTag && entry.packageTag.toLowerCase() === tagLower) return `${item.strain} (Batch ${item.lot})`;
    }
  }
  for (const l of (lineItems || [])) {
    if (l.packageTag && l.packageTag.toLowerCase() === tagLower) return `${l.strain} (Batch ${l.lot}) — already added to this manifest`;
  }
  return null;
}
// Trim entries record a trimmer's total weight only (grams), not a grade breakdown. Older entries
// from before this split still carry a gradeGrams object instead — this keeps both readable.
function trimEntryTotal(e) {
  if (e.grams != null) return e.grams;
  return Object.values(e.gradeGrams || {}).reduce((s, g) => s + g, 0);
}
function gradeEntryTotal(e) {
  return Object.values(e.gradeGrams || {}).reduce((s, g) => s + g, 0);
}
function QuickFillStrip({ items, renderLabel, onPick }) {
  if (!items || items.length === 0) return null;
  return (
    <div style={{ marginBottom: 10 }}>
      <div style={{ fontSize: 11, color: "#7C8571", marginBottom: 6 }}>Quick-fill from a recent batch:</div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
        {items.map((item) => (
          <button type="button" key={item.id} onClick={() => onPick(item)} style={styles.quickFillChip}>{renderLabel(item)}</button>
        ))}
      </div>
    </div>
  );
}

// Natural-order string compare so "F2" sorts before "F10" (alphabetical would reverse them). Splits
// each string into text/number chunks and compares chunk by chunk, numbers numerically.
function naturalCompare(a, b) {
  const ax = String(a == null ? "" : a).match(/(\d+|\D+)/g) || [];
  const bx = String(b == null ? "" : b).match(/(\d+|\D+)/g) || [];
  for (let i = 0; i < Math.max(ax.length, bx.length); i++) {
    const an = ax[i], bn = bx[i];
    if (an === undefined) return -1;
    if (bn === undefined) return 1;
    const aNum = /^\d+$/.test(an), bNum = /^\d+$/.test(bn);
    if (aNum && bNum) { const d = parseInt(an, 10) - parseInt(bn, 10); if (d !== 0) return d; }
    else { const c = an.localeCompare(bn); if (c !== 0) return c; }
  }
  return 0;
}
function fmtWeight(grams, unit) {
  if (unit === "lb") return (grams / G_PER_LB).toFixed(2) + " lb";
  return Math.round(grams).toLocaleString() + " g";
}
function fmtBoth(grams) {
  return `${(grams / G_PER_LB).toFixed(2)} lb (${Math.round(grams).toLocaleString()} g)`;
}
function toGrams(amount, unit) {
  const n = parseFloat(amount);
  if (isNaN(n)) return 0;
  return unit === "lb" ? n * G_PER_LB : n;
}
function fmtMoney(n) {
  return "$" + (n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// --- Zebra label printing (3.5in x 1in, 203dpi = 711 x 203 dots) ---
// ZPL text fields can't safely contain ^ or ~ (those are ZPL command characters),
// and the default printer codepage doesn't reliably support special typographic
// characters, so this keeps everything to plain ASCII.
function zplSafe(s) {
  return String(s == null ? "" : s).replace(/[\^~]/g, "").replace(/[^\x20-\x7E]/g, "");
}
function buildBatchLabelZPL(batch, shipper, unit) {
  const strain = zplSafe(batch.strain);
  const grade = zplSafe(batch.grade);
  const lot = zplSafe(batch.lot || "-");
  const sourceLabel = zplSafe(SOURCE_META[batch.source] ? SOURCE_META[batch.source].label : "");

  // A batch can carry more than one Metrc package tag across its deliveries — pull from every
  // addition (not just the batch's top-level field, which only ever mirrors the first one) so a
  // reprint days later never shows a stale or incomplete tag.
  const tags = Array.from(new Set(
    (batch.additions && batch.additions.length > 0 ? batch.additions.map((a) => a.packageTag) : [batch.packageTag]).filter(Boolean)
  ));
  const tagText = tags.length === 0 ? "" : tags.length === 1 ? `Tag ...${tags[0]}` : `Tags ...${tags.slice(0, 2).join(", ...")}${tags.length > 2 ? ` +${tags.length - 2}` : ""}`;

  // Label: 3.5" x 1" at 203 dpi = 711 x 203 dots. Text occupies the left ~535 dots; a QR code
  // sits on the right. QR encodes the full tag(s) + batch identity so a scan pulls real data,
  // even though the printed tag line is abbreviated to the last 4 for the human reader.
  const qrData = zplSafe(`${batch.strain} | ${sourceLabel} | Batch ${lot} | ${tags.length ? "Tag " + tags.join(", ") : "no tag"}`);

  return [
    "^XA",
    "^PW711",
    "^LL203",
    "^CI28",              // UTF-8, so strain names with accents print correctly
    // --- text block (left side) ---
    "^CF0,40",
    `^FO16,14^FB520,1,0,L^FD${strain} - ${grade}^FS`,
    "^CF0,30",
    `^FO16,66^FB520,1,0,L^FD${sourceLabel} / Batch ${lot}^FS`,
    "^CF0,28",
    tagText ? `^FO16,112^FB520,1,0,L^FD${zplSafe(tagText)}^FS` : "",
    shipperName(shipper) ? "^CF0,20" : "",
    shipperName(shipper) ? `^FO16,158^FB520,1,0,L^FD${zplSafe(shipperName(shipper))}^FS` : "",
    // --- QR code (right side) ---
    `^FO556,40^BQN,2,5^FDLA,${qrData}^FS`,
    "^XZ",
  ].filter(Boolean).join("\n");
}
function shipperName(shipper) { return shipper && shipper.name ? shipper.name : ""; }
function printZebraLabel(zpl) {
  return new Promise((resolve, reject) => {
    if (!window.BrowserPrint) {
      reject(new Error("Zebra Browser Print isn't detected on this computer. Make sure it's installed and running, then reload this page."));
      return;
    }
    window.BrowserPrint.getDefaultDevice(
      "printer",
      (device) => {
        if (!device) { reject(new Error("No Zebra printer found. Check that it's connected and powered on.")); return; }
        device.send(zpl, () => resolve(), (err) => reject(new Error(String(err) || "The printer didn't accept the label.")));
      },
      (err) => reject(new Error(String(err) || "Couldn't reach Zebra Browser Print.")));
  });
}

